struct anim_tree;

struct entity
{
    anim_tree *get_anim_tree(int) const;
};

struct anim_tree_vtable
{
    char padding[32];
    short adjustment;
    short reserved;
    void (*set_time)(void *, float);
};

struct anim_tree
{
    int padding;
    anim_tree_vtable *vtable;

    void set_time(float time)
    {
        anim_tree_vtable *table = vtable;
        table->set_time((char *)this + table->adjustment, time);
    }
};

struct world_dynamics_system
{
    void recompute_all_sectors();
    void frame_advance(float);
};

extern world_dynamics_system *g_world_ptr;
extern int StallSurferLoadSema;
extern int endMarker1;
extern int endMarker2;
extern int WaitSema(int);
extern int SignalSema(int);
extern int mem_set_checkpoint();

class FEEntityManager
{
    entity *surfer_ent;
    char padding[0x20];
    int loading_surfer_index;
    int loading_surfer_ent;

public:
    void LoadSurfer(int);
    void SetSurferPo(entity *, int);
    void SurferPlay(int, float = -1.0f, int = 0, int = 0, bool = false);
    void DoneAsyncLoad();
};

