asm(".equ SetSurferPo__15FEEntityManagerP6entityi, 0x001C9298");
asm(".equ SurferPlay__15FEEntityManagerifiib, 0x001C3118");

void FEEntityManager::DoneAsyncLoad()
{
    WaitSema(StallSurferLoadSema);
    LoadSurfer(loading_surfer_index);
    SetSurferPo(surfer_ent, loading_surfer_index);

    g_world_ptr->recompute_all_sectors();
    SurferPlay(0);
    if (surfer_ent->get_anim_tree(0))
        surfer_ent->get_anim_tree(0)->set_time(0);
    g_world_ptr->frame_advance(.01f);
    g_world_ptr->frame_advance(.01f);
    if (loading_surfer_ent)
        endMarker1 = mem_set_checkpoint();
    else
        endMarker2 = mem_set_checkpoint();

    SignalSema(StallSurferLoadSema);
}
